using System;

namespace AiBox.DevPortal.Models {
    public sealed class PatchTargetCorrectionResult {
        public bool IsCorrected { get; set; }
        public string OriginalPath { get; set; }
        public string CorrectedPath { get; set; }
        public string Reason { get; set; }
    }
}

using System;
using System.Collections.Generic;
using AiBox.DevPortal.Models;

namespace AiBox.DevPortal.Services {
    public class PatchTargetCorrectionService {
        public PatchTargetCorrectionResult CorrectPath(string requestedPath, IReadOnlyList<LocalCoderFileContext> selectedContexts) {
            if (selectedContexts.Any(x => x.FullPath == requestedPath)) {
                return new PatchTargetCorrectionResult { IsCorrected = false, OriginalPath = requestedPath, CorrectedPath = requestedPath, Reason = "Path already exists." };
            }

            string symbolName = InferSymbolNameFromFilename(requestedPath);
            if (string.IsNullOrEmpty(symbolName)) {
                return new PatchTargetCorrectionResult { IsCorrected = false, OriginalPath = requestedPath, CorrectedPath = requestedPath, Reason = "Unable to infer symbol name from filename." };
            }

            string correctedPath = FindSymbolPath(symbolName, selectedContexts);
            if (string.IsNullOrEmpty(correctedPath)) {
                return new PatchTargetCorrectionResult { IsCorrected = false, OriginalPath = requestedPath, CorrectedPath = requestedPath, Reason = "Symbol not found in selected contexts." };
            }

            return new PatchTargetCorrectionResult { IsCorrected = true, OriginalPath = requestedPath, CorrectedPath = correctedPath, Reason = "Path corrected successfully." };
        }

        private string InferSymbolNameFromFilename(string filename) {
            // Simplified logic to infer symbol name from filename
            return filename.Split(new char[] { '.', '_' }, StringSplitOptions.RemoveEmptyEntries).First();
        }

        private string FindSymbolPath(string symbolName, IReadOnlyList<LocalCoderFileContext> selectedContexts) {
            foreach (var context in selectedContexts) {
                if (context.Content.Contains($"class {symbolName}") ||
                    context.Content.Contains($"record {symbolName}") ||
                    context.Content.Contains($"interface {symbolName}")) {
                    return context.FullPath;
                }
            }
            return null;
        }
    }
}
